import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>给照片加文字只需要几分钟。上传图片、输入文字、选字体和颜色、把文字放到合适的位置，就完成了。</p>\n<p>这篇教程会一步步带你走完整个流程。包括单个与多个图层、字体与大小的选择、描边与阴影，以及让文字保持锐利的导出设置。</p>\n<p>读完之后，你能在任何设备上给照片加说明、做表情包、给截图贴标签，或者设计社交图片。检查结果之前，先留好原照片。</p>\n<h2 id=\"before-you-start\">开始之前：先把文字想好</h2>\n<p>打开工具之前先写好文字。提前想好的说明文字，比盯着编辑器现想的更短、更清晰。</p>\n<p>保持简短。几个词的标题加一行说明文字，效果远胜一段话；段落会遮住照片、压倒观众。</p>\n<p>再想想氛围。粗字体适合表情包或促销横幅，轻衬线字体适合婚礼照片或引用图片。</p>\n<p>打开<a href=\"/zh/tupian-tianjia-wenzi/\">图片加文字工具</a>。所有处理都在本地完成，照片不会上传到服务器。</p>\n<h2 id=\"step-by-step\">6步给图片加文字</h2>\n<p>说明文字、表情包、标签，流程都一样：上传、输入、定风格、放位置、检查、下载。</p>\n<p>定风格这一步值得花时间。字体、大小、颜色和描边，决定了文字是可读还是淹没在照片里。</p>\n<ol>\n<li>把图片拖进上传区，或者从设备里选择，也可以按Ctrl+V粘贴截图。</li>\n<li>点“添加文字”，在文字内容框里输入说明文字，需要换行就按回车。</li>\n<li>选一种字体，文字大小设置在2%到22%之间，再选一个和照片对比明显的颜色。</li>\n<li>背景复杂时加文字描边或阴影，然后把图层拖到位置上。</li>\n<li>需要更多行就加更多图层，逐个选中、分别定风格。</li>\n<li>选择导出格式和画质，点“下载”保存带文字的图片。</li>\n</ol>\n<p>分享之前先打开下载好的文件看一次。确认文字读得清楚，照片里重要的东西没有被遮住。</p>\n<h2 id=\"adding-your-first-layer\">添加第一个文字图层</h2>\n<p>点“添加文字”创建第一个图层。工具会在图片上放一个默认说明文字，你在文字内容框里把它换成自己的话。</p>\n<p>文字按你想显示的样子原样输入。图片上的拼写错误很难被忽略，所以继续之前把文字读两遍。</p>\n<p>图层默认出现在图片中央。把它拖到想要的位置，比如顶部放标题、底部放说明文字。</p>\n<p>每个图层都是独立的。一个图层可以用大号粗字体，另一个用小号轻字体，互不影响。</p>\n<h2 id=\"choosing-a-font\">选择字体</h2>\n<p>工具内置了一组字体，从粗无衬线字体到经典衬线字体都有。选一种符合图片氛围和你要表达的信息的字体。</p>\n<p>表情包和促销横幅用粗无衬线字体。粗壮的字母在小尺寸和复杂背景上依然可读，这正是表情包需要的。</p>\n<p>引用和婚礼照片用衬线或优雅字体。轻盈的笔画感觉正式平静，适合有思考感的信息。</p>\n<p>按实际使用的尺寸检查字体。装饰字体放大了看着漂亮，缩到小尺寸可能读不出来。</p>\n<h2 id=\"setting-text-size\">设置文字大小</h2>\n<p>文字大小从图片的2%到22%。标题需要接近范围上限的大尺寸，说明文字或署名需要小一点的尺寸。</p>\n<p>百分比设置让文字在不同尺寸的图片上保持一致。同样的设置，在小缩略图和大尺寸相机照片上看起来都合适。</p>\n<p>按实际分享的尺寸测试大小。全尺寸看着粗壮的标题，在社交信息流预览里可能很小，图片显示尺寸小得多。</p>\n<p>两个图层时，大小设得不一样。大标题加小说明文字，层次清晰，观众一下就知道先读什么。</p>\n<h2 id=\"choosing-a-colour\">选择文字颜色</h2>\n<p>白色文字适合深色背景，黑色文字适合浅色背景，但大多数照片两种背景都有。对着文字实际要放的区域检查颜色。</p>\n<p>把文字放在照片最平坦的部分。晴朗天空或空白墙面上的说明文字，比人群上的说明文字容易读得多。</p>\n<p>鲜艳颜色适合简短的标题，长说明文字里更难读。强烈的颜色留给几个词，其余用白色或黑色。</p>\n<p>没有颜色好用时，加一块背景板。白色文字后面放半透明的深色框，任何地方都可读，只不过遮住的图片面积更大了。</p>\n<h2 id=\"outline-and-shadow\">添加描边或阴影</h2>\n<p>描边是在每个字母周围画一圈边框。白色文字加细细的深色描边，在明亮天空上也能读，这就是表情包用它的原因。</p>\n<p>阴影把文字从背景上托起来。它在字母后面加一道柔和的深色边缘，帮助文字脱颖而出，又没有描边那么硬。</p>\n<p>两者选其一，不要同时开到最强。描边加浓重阴影会让文字看着杂乱，单一效果更干净。</p>\n<p>经典表情包文字用白色字母加粗深色描边。这种组合在几乎任何背景上都可读，所以成了标准做法。</p>\n<h2 id=\"moving-layers\">移动与选中图层</h2>\n<p>拖动图层可以把它移到图片上的任何位置。有多个图层时，可以逐个选中，改一个而不碰其他的。</p>\n<p>改字体、大小或颜色之前，先点一下想改的图层。改错图层是常见错误，检查一下当前选中的是哪一层就能避免。</p>\n<p>顶部和底部是说明文字的经典位置。顶部是标题、底部是笑点，这就是表情包的格式，符合自上而下的阅读习惯，所以好用。</p>\n<p>文字远离边缘。贴着边框的说明文字看着局促，平台还会为不同屏幕尺寸再次裁剪边缘。</p>\n<h2 id=\"rotating-text\">旋转文字图层</h2>\n<p>文字图层可以按自定义角度倾斜，给设计增加活力。略微倾斜的标题感觉灵动，端正的文字感觉平静正式。</p>\n<p>旋转要克制。倾斜几度能增加个性，角度太陡会让文字难读，看着像失误。</p>\n<p>斜文字适合海报和社交图片，设计就是要抓眼球。说明文字和标签则需要清晰，斜文字不合适。</p>\n<p>按实际查看的尺寸检查旋转后的文字。全尺寸看着好的倾斜，在信息流预览里可能让小字读不出来。</p>\n<h2 id=\"multi-line-captions\">多行说明文字与表情包布局</h2>\n<p>在文字内容框里按回车，可以在同一图层里换行。这样不用额外图层，就能写出两三行的说明文字。</p>\n<p>表情包顶部一行、底部一行，用两个图层分开。分开的图层可以把每行精确放到属于它的位置。</p>\n<p>每行保持简短。横贯整张图片的说明文字很难读，居中在主体上的短行更容易看。</p>\n<p>在句子自然停顿的地方换行。短语中间换行感觉别扭，短语之间换行感觉是特意的。</p>\n<h2 id=\"making-a-meme\">几分钟做一张表情包</h2>\n<p>表情包就是一张照片加一句简短有趣的说明文字，通常是顶部和底部带粗深色描边的白色文字。格式很简单，简单正是它的意义所在。</p>\n<p>上传照片，顶部加一层写铺垫，底部加一层写笑点。每行只留几个词，笑话才能快速到位。</p>\n<p>用粗壮有力的字体加深色描边。经典表情包的外观在几乎任何背景上都可读，所以成了标准做法。</p>\n<p>按实际分享的尺寸预览表情包。全尺寸看着清楚的笑话，在小信息流预览里可能读不出来，发布前先检查。</p>\n<h2 id=\"preview-and-export\">预览与导出</h2>\n<p>下载之前一定要预览。检查文字是否读得清楚、照片里重要的东西有没有被遮住、图层位置对不对。</p>\n<p>带文字的照片选JPG，用高画质设置导出。JPG压缩会让文字边缘略微变软，小说明文字要保持高画质。</p>\n<p>截图和带文字的图片选PNG。PNG是无损的，字母边缘保持锐利，需要时还能保留透明度。</p>\n<p>注意，PNG没有画质滑杆，因为PNG是无损的，没有画质可调。这很正常，不是工具出问题。</p>\n<h2 id=\"adding-text-on-mobile\">在手机或平板上加文字</h2>\n<p>工具支持触屏，可以直接在拍照的那部手机上给照片加说明。从相册上传，输入文字，手指把图层拖到位置上。</p>\n<p>手机键盘打字比较慢，所以打开工具之前先把说明文字写好。提前想好的简短说明，比现想的更容易输入。</p>\n<p>手指拖动图层不如鼠标精确。以中央、顶部和底部区域为参照，放大检查位置。</p>\n<p>下载的文件会进到你常用的下载文件夹。之后可以直接把带文字的图片分享到聊天软件、邮件或社交平台。</p>\n<h2 id=\"troubleshooting\">常见文字问题排查</h2>\n<p>文字读不出来，颜色可能和背景融在一起了。换颜色、加描边，或者把图层移到照片更平坦的部分。</p>\n<p>改错了图层，点一下本来想改的图层再试一次。工具一次只选中一个图层，定风格之前检查当前选中的是哪一层。</p>\n<p>图层拖不动，检查是不是先选中了它。图层必须处于选中状态才能拖动，通常点一次就能选中。</p>\n<p>导出后文字看着模糊，JPG画质设置可能太低了。换高画质重新导出，或者换PNG，文字边缘最锐利。</p>\n<h2 id=\"quick-tips\">图片文字更好的小技巧</h2>\n<p>文字保持简短。几句选得好的词能强化图片，一段塞满照片的文字反而会遮住它本来要表达的东西。</p>\n<p>标题一种字体、说明文字一种字体，最多两种。混用太多字形看着混乱，一致的搭配让设计保持干净。</p>\n<p>按实际查看的尺寸检查文字。全尺寸看着好的说明文字，在社交信息流预览里可能读不出来。</p>\n<p>留好没有文字的原照片。文字一旦压进导出文件就去不掉了，原文件是唯一的干净副本。</p>\n<h2 id=\"text-on-presentation-slides\">给演示文稿配图加文字</h2>\n<p>用作幻灯片背景的照片，常常需要在上面加标题。用大号粗字体加一层文字图层，从教室后排也能看清。</p>\n<p>标题放在照片最平坦的部分。晴朗天空或空白墙面上的标题，比人群上的标题容易读得多。</p>\n<p>背景复杂时用深色描边或阴影。效果刚好把字母从照片上托起来、够读，又不遮住下面的图片。</p>\n<p>幻灯片图片导出用高画质JPG。幻灯片投影放大后，文字要保持锐利，低画质导出会让字母变软。</p>\n<p>可读性规则读<a href=\"/zh/blog/tupian-wenzi-qingxi-kedu-jiqiao/\">图片文字：字体、对比度与可读性</a>。完整概览见<a href=\"/zh/blog/tupian-jia-wenzi-wanquan-zhinan/\">图片加文字完全指南</a>；想标记归属而不是加说明文字，可以用<a href=\"/zh/tianjia-shuiyin/\">图片水印工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"手机上怎么给照片加文字？","answer":"在手机浏览器里打开图片加文字工具，从相册上传照片，点“添加文字”。输入说明文字，选字体和大小，手指把图层拖到位置上，下载结果。"},{"question":"一张图片能加两个不同的说明文字吗？","answer":"能。每个说明文字单独加一个图层，比如一个在顶部、一个在底部。逐个选中图层分别定风格，标题可以大而粗，说明文字保持小一点。"},{"question":"为什么下载后文字看着模糊？","answer":"JPG画质设置可能太低了，字母边缘被柔化了。换高画质重新导出，或者换PNG，PNG是无损的，文字边缘保持锐利。"},{"question":"经典的上下文字表情包怎么做？","answer":"上传照片，顶部加一层写第一行，底部加一层写第二行，用粗无衬线字体，白色加粗深色描边。每行只留几个词，笑话才能快速到位。"},{"question":"文字输入后还能移动吗？","answer":"能。选中图层，拖到图片上的任何位置。下载之前，图层随时可以移动、改大小、换颜色、旋转。图片一旦导出，文字就压进去了，移不动了。"},{"question":"Instagram帖子上的文字要多大？","answer":"大到在小信息流预览里也能读，不只是全尺寸下可读。标题要用2%到22%范围里接近上限的尺寸。导出后按信息流里的实际尺寸看一眼再发布。"}];
